using System;using System.Collections.Generic;public class Solution{int F(int[]p,int x)=>p[x]==x?x:(p[x]=F(p,p[x]));public IList<int> NumIslands2(int m,int n,int[][]pos){int[]p=new int[m*n];Array.Fill(p,-1);var o=new List<int>();int c=0;int[][]d={new[]{1,0},new[]{-1,0},new[]{0,1},new[]{0,-1}};foreach(var v in pos){int r=v[0],q=v[1],id=r*n+q;if(p[id]!=-1){o.Add(c);continue;}p[id]=id;c++;foreach(var z in d){int a=r+z[0],b=q+z[1];if(a<0||b<0||a>=m||b>=n||p[a*n+b]==-1)continue;int x=F(p,id),y=F(p,a*n+b);if(x!=y){p[x]=y;c--;}}o.Add(c);}return o;}}
